const j = $json;
const slug = String(j['Client name']).replace(/[^A-Za-z0-9 ]/g, '').trim().split(' ').join('_');
const uk = j['Region'] === 'UK';
const checklist = ['Bank statements (last 3 months, all accounts)', 'Credit card statements', 'Sales invoices issued this year', 'Purchase invoices and receipts', uk ? 'VAT registration details and last VAT return' : 'State sales tax registration details (if any)', 'Payroll summary (if applicable)', 'Prior year filed accounts / tax return', 'Loan agreements and statements', 'Signed authority form (to deal with the tax authority on your behalf)'];
return { json: { client: j['Client name'], slug: slug, email: j['Contact email'], region: j['Region'], entity: j['Entity type'], services: j['Services'], fee: j['Monthly fee'], start: j['Start date'], currency: uk ? 'GBP' : 'USD', checklist: checklist, checklist_text: checklist.map((c, i) => (i + 1) + '. ' + c).join('\n') } };

const c = $('Normalize Intake').first().json;
const steps = ['Review signed engagement letter', 'Confirm bank feeds and software access', 'Receive first documents', 'Kickoff call', 'First month bookkeeping starts'];
const due = [2, 3, 5, 5, 10];
return steps.map((s, i) => ({ json: { client: c.client, task: s, owner: 'Bookkeeper', status: 'Open', due_in_days: due[i], created: new Date().toISOString() } }));
